div.script:
async function fetchAndInject(e) {
  if (e) { e.preventDefault(); e.stopPropagation(); }

  const iframe = document.getElementById('target-iframe');
  const url = 'https://cdn.jsdelivr.net/gh/zaka13x/zaka13X@master/index.html'; 

  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error('HTTP ' + response.status);

    let htmlText = await response.text();

    // FIX 2: Optional safeguard. If your fetched CDN file contains inline script blocks
    // defined like , the XML parser inside the SVG might sometimes choke on them 
    // depending on how they are nested. Passing the raw string directly via srcdoc handles it:
    iframe.srcdoc = htmlText; 

  } catch (err) {
    iframe.srcdoc = '<p style="color:red; font-size:18px; padding:20px;">Failed: ' + err.message + '</p>';
  }
}
